function runSameChecker(control) {
 const stdout = [];
 const stderr = [];
 const reads = new Set();
 let exitCode = null;
 const inputs = new Map(Object.entries(control.overlays).map(([name, sql]) => [path.join(migrationDir, name), sql]));
 const adapter = {
  readFileSync(file, encoding) {
   const absolute = path.resolve(String(file));
   reads.add(absolute);
   if (!inputs.has(absolute) && !cachedInputs.has(absolute)) cachedInputs.set(absolute, fs.readFileSync(absolute, 'utf8'));
   const content = inputs.get(absolute) ?? cachedInputs.get(absolute);
   return encoding === 'utf8' ? content : Buffer.from(content);
  },
  readdirSync(directory) {
   assert.equal(path.resolve(String(directory)), migrationDir);
   return [...originalNames, ...Object.keys(control.overlays)].sort();
  }
 };
 const context = {
  require(name) { if (name === 'fs') return adapter; if (name === 'path') return path; throw Error('unexpected checker require: ' + name); },
  process: { cwd: () => taskRoot, exit(code) { exitCode = code; } },
  console: { log(...parts) { stdout.push(parts.join(' ')); }, error(...parts) { stderr.push(parts.join(' ')); } }
 };
 let runtimeError = null;
 try { vm.runInNewContext(checker, context, { filename: scriptPath, timeout: 10000 }); } catch (error) { runtimeError = String(error.stack ?? error); }
 return { exitCode, stdout, stderr, runtimeError, readCount: reads.size, readPaths: [...reads].sort() };
}

